CREATE TYPE "MonetizationStatus" AS ENUM ('DRAFT','ACTIVE','RETIRED');
CREATE TYPE "MonetizationPricingModel" AS ENUM ('FIXED','RECURRING','USAGE','TIERED','PER_SEAT','PER_LOCATION','PER_PROFESSIONAL','TRANSACTION','COMMISSION','HYBRID');
CREATE TYPE "MonetizationBillingInterval" AS ENUM ('ONE_TIME','MONTHLY','ANNUAL');
CREATE TYPE "MonetizationSubscriptionStatus" AS ENUM ('TRIAL','ACTIVE','PAST_DUE','PAUSED','CANCELLED','EXPIRED');
CREATE TYPE "FinancialLedgerEntryType" AS ENUM ('CHARGE','COMMISSION','PLATFORM_FEE','REFUND','CREDIT','PAYOUT','ADJUSTMENT','REVERSAL');
CREATE TYPE "FinancialSettlementStatus" AS ENUM ('OPEN','FINALIZED','PAYOUT_PENDING','PAID','CANCELLED');
CREATE TYPE "FinancialPayoutStatus" AS ENUM ('PENDING','PROCESSING','PAID','FAILED','REVERSED');
CREATE TABLE "MonetizationPlan" ("id" TEXT PRIMARY KEY,"marketId" TEXT NOT NULL REFERENCES "Market"("id") ON DELETE RESTRICT,"key" TEXT NOT NULL,"status" "MonetizationStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("marketId","key"));
CREATE TABLE "MonetizationPlanVersion" ("id" TEXT PRIMARY KEY,"planId" TEXT NOT NULL REFERENCES "MonetizationPlan"("id") ON DELETE RESTRICT,"version" INTEGER NOT NULL,"name" TEXT NOT NULL,"status" "MonetizationStatus" NOT NULL DEFAULT 'DRAFT',"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveTo" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("planId","version"));
CREATE TABLE "PlanEntitlement" ("id" TEXT PRIMARY KEY,"planVersionId" TEXT NOT NULL REFERENCES "MonetizationPlanVersion"("id") ON DELETE CASCADE,"key" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"limitValue" BIGINT,"configuration" JSONB,UNIQUE("planVersionId","key"));
CREATE TABLE "MonetizationPriceVersion" ("id" TEXT PRIMARY KEY,"planVersionId" TEXT NOT NULL REFERENCES "MonetizationPlanVersion"("id") ON DELETE RESTRICT,"version" INTEGER NOT NULL,"model" "MonetizationPricingModel" NOT NULL,"amountMinor" BIGINT NOT NULL,"currency" CHAR(3) NOT NULL,"billingInterval" "MonetizationBillingInterval" NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveTo" TIMESTAMP(3),"configuration" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("planVersionId","version"));
CREATE TABLE "BillingAccount" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL UNIQUE REFERENCES "Business"("id") ON DELETE RESTRICT,"providerCustomerRef" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "MonetizationSubscription" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,"billingAccountId" TEXT NOT NULL REFERENCES "BillingAccount"("id") ON DELETE RESTRICT,"planVersionId" TEXT NOT NULL REFERENCES "MonetizationPlanVersion"("id") ON DELETE RESTRICT,"status" "MonetizationSubscriptionStatus" NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"trialEndsAt" TIMESTAMP(3),"currentPeriodStart" TIMESTAMP(3) NOT NULL,"currentPeriodEnd" TIMESTAMP(3) NOT NULL,"cancelAtPeriodEnd" BOOLEAN NOT NULL DEFAULT false,"cancelledAt" TIMESTAMP(3),"providerSubscriptionRef" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SubscriptionItem" ("id" TEXT PRIMARY KEY,"subscriptionId" TEXT NOT NULL REFERENCES "MonetizationSubscription"("id") ON DELETE RESTRICT,"priceVersionId" TEXT NOT NULL,"quantity" BIGINT NOT NULL DEFAULT 1,UNIQUE("subscriptionId","priceVersionId"));
CREATE TABLE "SubscriptionChange" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"subscriptionId" TEXT NOT NULL REFERENCES "MonetizationSubscription"("id") ON DELETE RESTRICT,"fromStatus" "MonetizationSubscriptionStatus" NOT NULL,"toStatus" "MonetizationSubscriptionStatus" NOT NULL,"reason" TEXT NOT NULL,"actorId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MonetizationUsageMeter" ("id" TEXT PRIMARY KEY,"metric" TEXT NOT NULL UNIQUE,"unit" TEXT NOT NULL,"aggregation" TEXT NOT NULL,"status" "MonetizationStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MonetizationUsageRecord" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,"marketId" TEXT NOT NULL,"meterId" TEXT REFERENCES "MonetizationUsageMeter"("id") ON DELETE RESTRICT,"metric" TEXT NOT NULL,"quantity" BIGINT NOT NULL,"source" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL,"correlationId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("businessId","idempotencyKey"));
CREATE TABLE "FinancialPricingRule" ("id" TEXT PRIMARY KEY,"marketId" TEXT NOT NULL REFERENCES "Market"("id") ON DELETE RESTRICT,"key" TEXT NOT NULL,"version" INTEGER NOT NULL,"model" "MonetizationPricingModel" NOT NULL,"configuration" JSONB NOT NULL,"currency" CHAR(3) NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveTo" TIMESTAMP(3),"status" "MonetizationStatus" NOT NULL DEFAULT 'DRAFT',UNIQUE("marketId","key","version"));
CREATE TABLE "CommissionRule" ("id" TEXT PRIMARY KEY,"marketId" TEXT NOT NULL REFERENCES "Market"("id") ON DELETE RESTRICT,"merchantBusinessId" TEXT,"categoryId" TEXT,"campaignId" TEXT,"version" INTEGER NOT NULL,"fixedMinor" BIGINT NOT NULL DEFAULT 0,"percentageBasisPoints" INTEGER NOT NULL,"minimumMinor" BIGINT,"maximumMinor" BIGINT,"currency" CHAR(3) NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveTo" TIMESTAMP(3),"status" "MonetizationStatus" NOT NULL DEFAULT 'DRAFT');
CREATE TABLE "FinancialPromotion" ("id" TEXT PRIMARY KEY,"marketId" TEXT NOT NULL REFERENCES "Market"("id") ON DELETE RESTRICT,"code" TEXT NOT NULL,"version" INTEGER NOT NULL,"type" TEXT NOT NULL,"value" BIGINT NOT NULL,"currency" TEXT,"configuration" JSONB NOT NULL,"validFrom" TIMESTAMP(3) NOT NULL,"validTo" TIMESTAMP(3) NOT NULL,"status" "MonetizationStatus" NOT NULL DEFAULT 'DRAFT',UNIQUE("marketId","code","version"));
CREATE TABLE "PromotionRedemption" ("id" TEXT PRIMARY KEY,"promotionId" TEXT NOT NULL REFERENCES "FinancialPromotion"("id") ON DELETE RESTRICT,"businessId" TEXT NOT NULL,"userId" TEXT,"amountMinor" BIGINT NOT NULL,"currency" CHAR(3) NOT NULL,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("businessId","idempotencyKey"));
CREATE TABLE "FinancialLedgerEntry" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,"type" "FinancialLedgerEntryType" NOT NULL,"amountMinor" BIGINT NOT NULL,"currency" CHAR(3) NOT NULL,"revenueStream" TEXT,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"reason" TEXT NOT NULL,"actorId" TEXT,"correlationId" TEXT,"reversalOfId" TEXT REFERENCES "FinancialLedgerEntry"("id") ON DELETE RESTRICT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("businessId","idempotencyKey"));
CREATE TABLE "RefundRecord" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,"originalEntryId" TEXT NOT NULL REFERENCES "FinancialLedgerEntry"("id") ON DELETE RESTRICT,"ledgerEntryId" TEXT NOT NULL UNIQUE,"amountMinor" BIGINT NOT NULL,"currency" CHAR(3) NOT NULL,"idempotencyKey" TEXT NOT NULL,"reason" TEXT NOT NULL,"actorId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("businessId","idempotencyKey"));
CREATE TABLE "FinancialCreditGrant" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,"userId" TEXT,"amountMinor" BIGINT NOT NULL,"currency" CHAR(3) NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3),"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("businessId","idempotencyKey"));
CREATE TABLE "FinancialCreditConsumption" ("id" TEXT PRIMARY KEY,"grantId" TEXT NOT NULL REFERENCES "FinancialCreditGrant"("id") ON DELETE RESTRICT,"amountMinor" BIGINT NOT NULL,"ledgerEntryId" TEXT NOT NULL UNIQUE,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("grantId","idempotencyKey"));
CREATE TABLE "FinancialSettlement" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,"periodStart" TIMESTAMP(3) NOT NULL,"periodEnd" TIMESTAMP(3) NOT NULL,"currency" CHAR(3) NOT NULL,"grossMinor" BIGINT NOT NULL,"commissionMinor" BIGINT NOT NULL,"feeMinor" BIGINT NOT NULL,"refundMinor" BIGINT NOT NULL,"adjustmentMinor" BIGINT NOT NULL,"netPayableMinor" BIGINT NOT NULL,"status" "FinancialSettlementStatus" NOT NULL DEFAULT 'OPEN',"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"finalizedAt" TIMESTAMP(3),UNIQUE("businessId","idempotencyKey"));
CREATE TABLE "FinancialPayout" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,"settlementId" TEXT NOT NULL UNIQUE REFERENCES "FinancialSettlement"("id") ON DELETE RESTRICT,"amountMinor" BIGINT NOT NULL,"currency" CHAR(3) NOT NULL,"status" "FinancialPayoutStatus" NOT NULL DEFAULT 'PENDING',"providerPayoutRef" TEXT,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("businessId","idempotencyKey"));
CREATE TABLE "AICostConfiguration" ("id" TEXT PRIMARY KEY,"marketId" TEXT NOT NULL REFERENCES "Market"("id") ON DELETE RESTRICT,"provider" TEXT NOT NULL,"model" TEXT NOT NULL,"version" INTEGER NOT NULL,"currency" CHAR(3) NOT NULL,"inputPerMillionMinor" BIGINT NOT NULL,"outputPerMillionMinor" BIGINT NOT NULL,"toolExecutionMinor" BIGINT NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveTo" TIMESTAMP(3),"status" "MonetizationStatus" NOT NULL DEFAULT 'DRAFT',UNIQUE("marketId","provider","model","version"));
CREATE TABLE "FinancialMetricSnapshot" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,"periodStart" TIMESTAMP(3) NOT NULL,"periodEnd" TIMESTAMP(3) NOT NULL,"currency" CHAR(3) NOT NULL,"metrics" JSONB NOT NULL,"calculationVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("businessId","periodStart","periodEnd","calculationVersion"));
CREATE TABLE "UnitEconomicsSnapshot" ("id" TEXT PRIMARY KEY,"marketId" TEXT NOT NULL,"periodStart" TIMESTAMP(3) NOT NULL,"periodEnd" TIMESTAMP(3) NOT NULL,"currency" CHAR(3) NOT NULL,"metrics" JSONB NOT NULL,"dataState" TEXT NOT NULL,"calculationVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("marketId","periodStart","periodEnd","calculationVersion"));
CREATE INDEX "MonetizationSubscription_businessId_status_idx" ON "MonetizationSubscription"("businessId","status");
CREATE INDEX "MonetizationUsageRecord_businessId_metric_occurredAt_idx" ON "MonetizationUsageRecord"("businessId","metric","occurredAt");
CREATE INDEX "FinancialLedgerEntry_businessId_type_createdAt_idx" ON "FinancialLedgerEntry"("businessId","type","createdAt");
CREATE INDEX "RefundRecord_businessId_originalEntryId_idx" ON "RefundRecord"("businessId","originalEntryId");
CREATE INDEX "FinancialSettlement_businessId_status_periodStart_periodEnd_idx" ON "FinancialSettlement"("businessId","status","periodStart","periodEnd");
CREATE TABLE "PaymentWebhookEvent" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,"eventId" TEXT NOT NULL UNIQUE,"eventType" TEXT NOT NULL,"resourceReference" TEXT NOT NULL,"payloadHash" TEXT NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "PaymentWebhookEvent_businessId_eventType_receivedAt_idx" ON "PaymentWebhookEvent"("businessId","eventType","receivedAt");
